// Innvadex languages: English, Spanish, French, and Mandarin Chinese.
// The game writes every sentence in English and passes it through t(). t() looks the sentence
// up here and shows it in the player's language. If a sentence is missing, it stays in English.
//
// To fix a translation: find the English sentence below and change the words in the list
// [Spanish, French]. Keep anything in {curly brackets} exactly the same, because the game
// puts numbers and names there. `node scripts/check.js` checks that nothing is missing.
// Bug names, people's names (like Ranger Fern and Pip), and "Innvadex" stay the same in every language.
//
// Spanish and French are in the lists below. Mandarin has its own file, assets/i18n/zh.js, which adds
// { "English sentence": "translation" } to GAME_EXTRA (more languages can be added the same way).

const GAME_LANGS = { en: "English", es: "Español", fr: "Français", zh: "中文（普通话）" };
const GAME_LANG_INDEX = { es: 0, fr: 1 };   // the position of each language in the lists below
// The name browsers use for each language (for fonts, dates, and read-aloud voices)
const GAME_LANG_TAGS = { en: "en-US", es: "es-ES", fr: "fr-FR", zh: "zh-CN" };
const GAME_EXTRA = {};   // filled in by the files in assets/i18n/
let gameLang = "en";
const langTag = () => GAME_LANG_TAGS[gameLang] || "en-US";

function t(text, vars) {
  const i = GAME_LANG_INDEX[gameLang];
  let out = (i != null && GAME_I18N[text]?.[i]) || GAME_EXTRA[gameLang]?.[text] || text;
  if (vars) out = out.replace(/\{(\w+)\}/g, (m, k) => vars[k] != null ? vars[k] : m);
  return out;
}

// Switches the game's language and translates the words written in index.html (data-i18n)
function setLanguage(lang) {
  gameLang = GAME_LANGS[lang] ? lang : "en";
  for (const id of ["game", "gamePopup", "gameToast", "gameCamera"]) { const e = document.getElementById(id); if (e) e.lang = langTag(); }
  for (const e of document.querySelectorAll("[data-i18n]")) e.textContent = t(e.dataset.i18n);
  const pick = document.getElementById("langSelect");
  if (pick) pick.value = gameLang;
}

